(function() {
    var successMessage = document.getElementById('newsletterSuccessMessage');
    var successClose = document.getElementById('newsletterSuccessClose');
    function hideSuccessMessage() {
      if (successMessage) successMessage.style.display = 'none';
    }
    if (successClose) successClose.addEventListener('click', hideSuccessMessage);
    var params = new URLSearchParams(window.location.search);
    var nl = document.getElementById('nlContent');
    var nlSection = document.getElementById('newsletter');

    function revealNlContent() {
      if (!nl) return;
      nl.classList.remove('nl-hidden');
      nl.classList.add('nl-visible');
      var el = document.getElementById('nlCounter');
      var target = 500; var current = 0; var step = Math.ceil(target / 40);
      var t = setInterval(function() {
        current = Math.min(current + step, target);
        if (el) el.textContent = current;
        if (current >= target) clearInterval(t);
      }, 40);
    }

    if (successMessage && params.get('subscribed') === '1') {
      revealNlContent();
      successMessage.style.display = 'block';
      setTimeout(function() {
        if (nlSection) nlSection.scrollIntoView({ behavior: 'auto', block: 'end' });
      }, 0);
      setTimeout(hideSuccessMessage, 6000);
      if (window.history && window.history.replaceState) {
        params.delete('subscribed');
        var q = params.toString();
        var cleanUrl = window.location.pathname + (q ? '?' + q : '') + window.location.hash;
        window.history.replaceState({}, document.title, cleanUrl);
      }
    }

    if (nl && params.get('subscribed') !== '1') {
      var obs = new IntersectionObserver(function(entries) {
        if (entries[0].isIntersecting) {
          revealNlContent();
          obs.disconnect();
        }
      }, { threshold: 0.3 });
      obs.observe(nl);
    }

    var inlineNlForm = document.querySelector('#newsletter form[action*="formsubmit"]');
    if (inlineNlForm) {
      inlineNlForm.addEventListener('submit', function() {
        if (window.plausible) {
          plausible('Newsletter-Submit', { props: { page: 'services', source: 'inline' } });
        }
      });
    }
  })();

(function () {
      'use strict';

      var nav = document.getElementById('nav');
      var hamburger = (document.getElementById("__legacy_hamburgerBtn") || document.createElement("button"));
      var mobileMenu = (document.getElementById("__legacy_mobileMenu") || document.createElement("div"));

      // Rotating live weather in menu
      var WEATHER_CITIES = [
        { name: 'לונדון',    lat: 51.51, lon: -0.12 },
        { name: 'בודפשט',   lat: 47.50, lon: 19.04 },
        { name: 'וינה',      lat: 48.21, lon: 16.37 },
        { name: 'אתונה',     lat: 37.98, lon: 23.73 },
        { name: 'פראג',      lat: 50.08, lon: 14.44 },
        { name: 'ורשה',      lat: 52.23, lon: 21.01 },
        { name: 'ברטיסלבה', lat: 48.15, lon: 17.11 },
        { name: 'ברצלונה',  lat: 41.39, lon:  2.17 },
        { name: 'אמסטרדם',  lat: 52.37, lon:  4.90 },
        { name: 'רומא',      lat: 41.90, lon: 12.49 },
      ];
      var weatherCityIndex = Math.floor(Math.random() * WEATHER_CITIES.length);

      function fetchMenuWeather() {
        var el = (document.getElementById("__legacy_menuWeatherSnippet") || document.createElement("span"));
        if (!el) return;
        weatherCityIndex = (weatherCityIndex + 1) % WEATHER_CITIES.length;
        var city = WEATHER_CITIES[weatherCityIndex];
        el.textContent = city.name + '...';
        fetch('https://api.open-meteo.com/v1/forecast?latitude=' + city.lat + '&longitude=' + city.lon + '&current_weather=true')
          .then(function(r) { return r.json(); })
          .then(function(d) {
            var t = Math.round(d.current_weather.temperature);
            var code = d.current_weather.weathercode;
            var icon = code <= 1 ? '☀️' : code <= 3 ? '⛅' : code <= 67 ? '🌧' : '❄️';
            el.textContent = city.name + ' עכשיו ' + t + '°C ' + icon;
          })
          .catch(function() { el.textContent = 'מזג אוויר באירופה'; });
      }

      if (hamburger && mobileMenu) {
        hamburger.addEventListener('click', function () {
          var isOpen = mobileMenu.classList.toggle('open');
          hamburger.setAttribute('aria-expanded', isOpen.toString());
          hamburger.setAttribute('aria-label', isOpen ? 'סגור תפריט' : 'פתח תפריט');
          document.body.style.overflow = isOpen ? 'hidden' : '';
          if (isOpen) fetchMenuWeather();
        });

        mobileMenu.querySelectorAll('a').forEach(function (link) {
          link.addEventListener('click', function () {
            mobileMenu.classList.remove('open');
            hamburger.setAttribute('aria-expanded', 'false');
            hamburger.setAttribute('aria-label', 'פתח תפריט');
            document.body.style.overflow = '';
          });
        });
      }

      if (nav) {
        window.addEventListener('scroll', function () {
          nav.classList.toggle('scrolled', window.scrollY > 10);
        }, { passive: true });
      }

      var reveals = document.querySelectorAll('.reveal');

      if ('IntersectionObserver' in window) {
        var observer = new IntersectionObserver(function (entries) {
          entries.forEach(function (entry) {
            if (entry.isIntersecting) {
              entry.target.classList.add('visible');
              observer.unobserve(entry.target);
            }
          });
        }, {
          threshold: 0.15,
          rootMargin: '0px 0px -40px 0px'
        });

        reveals.forEach(function (el) {
          observer.observe(el);
        });
      } else {
        reveals.forEach(function (el) {
          el.classList.add('visible');
        });
      }

      var faqItems = document.querySelectorAll('.faq__item');

      faqItems.forEach(function (item) {
        var questionBtn = item.querySelector('.faq__question');
        var answer = item.querySelector('.faq__answer');

        questionBtn.addEventListener('click', function () {
          var isOpen = item.getAttribute('data-open') === 'true';

          faqItems.forEach(function (otherItem) {
            if (otherItem !== item) {
              otherItem.setAttribute('data-open', 'false');
              otherItem.querySelector('.faq__question').setAttribute('aria-expanded', 'false');
              otherItem.querySelector('.faq__answer').style.maxHeight = null;
            }
          });

          if (isOpen) {
            item.setAttribute('data-open', 'false');
            questionBtn.setAttribute('aria-expanded', 'false');
            answer.style.maxHeight = null;
          } else {
            item.setAttribute('data-open', 'true');
            questionBtn.setAttribute('aria-expanded', 'true');
            answer.style.maxHeight = answer.scrollHeight + 'px';
          }
        });
      });

      document.addEventListener('keydown', function (e) {
        if (e.key === 'Escape' && mobileMenu.classList.contains('open')) {
          mobileMenu.classList.remove('open');
          hamburger.setAttribute('aria-expanded', 'false');
          hamburger.setAttribute('aria-label', 'פתח תפריט');
          document.body.style.overflow = '';
          hamburger.focus();
        }
      });

      var contactModal = document.getElementById('contactModal');
      var openBtn = document.getElementById('openContactModal');
      var closeBtn = document.getElementById('closeContactModal');
      var submitBtn = document.getElementById('submitContact');
      var contactForm = document.getElementById('contactForm');
      var modalSuccess = document.getElementById('modalSuccess');

      function openModal() {
        contactModal.classList.add('active');
        contactModal.setAttribute('aria-hidden', 'false');
        document.body.style.overflow = 'hidden';
        setTimeout(function() {
          document.getElementById('contactName').focus();
        }, 300);
      }

      function openContactModalWithPackage(packageName) {
        openModal();
        setTimeout(function() {
          document.getElementById('contactMessage').value = 'אני מתעניין בחבילת ' + packageName;
        }, 320);
      }
      window.openContactModalWithPackage = openContactModalWithPackage;

      function closeModal() {
        contactModal.classList.remove('active');
        contactModal.setAttribute('aria-hidden', 'true');
        document.body.style.overflow = '';
        setTimeout(function() {
          contactForm.style.display = '';
          modalSuccess.style.display = 'none';
          document.querySelector('.modal__title').style.display = '';
          document.querySelector('.modal__subtitle').style.display = '';
          document.getElementById('contactName').value = '';
          document.getElementById('contactEmail').value = '';
          document.getElementById('contactMessage').value = '';
          var errorFields = contactModal.querySelectorAll('.error');
          errorFields.forEach(function(f) { f.classList.remove('error'); });
        }, 300);
      }

      if (openBtn) openBtn.addEventListener('click', openModal);
      closeBtn.addEventListener('click', closeModal);

      contactModal.addEventListener('click', function(e) {
        if (e.target === contactModal) closeModal();
      });

      document.addEventListener('keydown', function(e) {
        if (e.key === 'Escape' && contactModal.classList.contains('active')) {
          closeModal();
        }
      });

      submitBtn.addEventListener('click', function() {
        var name = document.getElementById('contactName');
        var email = document.getElementById('contactEmail');
        var message = document.getElementById('contactMessage');
        var valid = true;

        [name, email, message].forEach(function(f) { f.classList.remove('error'); });

        if (!name.value.trim()) { name.classList.add('error'); valid = false; }
        if (!email.value.trim() || !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email.value)) { email.classList.add('error'); valid = false; }
        if (!message.value.trim()) { message.classList.add('error'); valid = false; }

        if (!valid) return;

        submitBtn.disabled = true;
        submitBtn.textContent = 'שולח...';

        var formData = new FormData();
        formData.append('name', name.value.trim());
        formData.append('email', email.value.trim());
        formData.append('message', message.value.trim());
        formData.append('_subject', 'פנייה חדשה מאתר מתי טסים');

        fetch('https://formspree.io/f/__FORM_WEBSITE__', { method: 'POST', body: formData, headers: { Accept: 'application/json' } }).then(function (r) { if (!r.ok) throw new Error('form'); return r; })
        .then(function(response) { return response.json(); })
        .then(function(data) {
          contactForm.style.display = 'none';
          document.querySelector('.modal__title').style.display = 'none';
          document.querySelector('.modal__subtitle').style.display = 'none';
          modalSuccess.style.display = 'block';
          if (window.plausible) {
            plausible('Services-Contact-Submit', { props: { page: 'services' } });
          }
          submitBtn.disabled = false;
          submitBtn.textContent = 'שלח פנייה';
        })
        .catch(function() {
          var subject = encodeURIComponent('פנייה מאתר מתי טסים - ' + name.value.trim());
          var body = encodeURIComponent('שם: ' + name.value.trim() + '\nאימייל: ' + email.value.trim() + '\n\n' + message.value.trim());
          window.location.href = 'mailto:info@mataytasim.co.il?subject=' + subject + '&body=' + body;
          submitBtn.disabled = false;
          submitBtn.textContent = 'שלח פנייה';
          closeModal();
        });
      });

    })();

