(function() {
    var API_URL    = 'https://mataytasim-ticketmasterm-api-imjw.vercel.app/api/events';
    var SEARCH_URL = 'https://mataytasim-ticketmasterm-api-imjw.vercel.app/api/search';
    var eventsData = null;
    var activeCategory = 'music';
    var loaded = false;
    var searchMode = false;

    var CATEGORY_ICONS = {
      music:   '🎵',
      arts:    '🎭',
      family:  '👨‍👩‍👧',
      comedy:  '😂',
      sports:  '⚽',
    };
    var COUNTRY_FLAGS = {
      AT: '🇦🇹', CZ: '🇨🇿', GR: '🇬🇷',
      PL: '🇵🇱', RO: '🇷🇴', SK: '🇸🇰'
    };

    // Show events FAB only when ?events=true is in the URL
    if (new URLSearchParams(window.location.search).get('events') === 'true') {
      document.getElementById('events-fab-btn').style.display = 'flex';
    }

    var drawer   = document.getElementById('events-drawer');
    var overlay  = document.getElementById('events-overlay');
    var fabBtn   = document.getElementById('events-fab-btn');
    var closeBtn = document.getElementById('events-drawer-close');
    var content  = document.getElementById('events-drawer-content');

    function openDrawer() {
      drawer.classList.add('open');
      overlay.classList.add('open');
      document.body.style.overflow = 'hidden';
      if (!loaded) fetchEvents();
    }

    function closeDrawer() {
      drawer.classList.remove('open');
      overlay.classList.remove('open');
      document.body.style.overflow = '';
    }

    fabBtn.addEventListener('click', openDrawer);
    closeBtn.addEventListener('click', closeDrawer);
    overlay.addEventListener('click', closeDrawer);
    document.addEventListener('keydown', function(e) {
      if (e.key === 'Escape') closeDrawer();
    });

    function formatDate(dateStr) {
      if (!dateStr) return '';
      var p = dateStr.split('-');
      return p[2] + '/' + p[1] + '/' + p[0];
    }

    function renderCards(category) {
      var allEvents = (eventsData && eventsData.events[category]) || [];
      var icon = CATEGORY_ICONS[category] || '🎟';

      // Deduplicate by name (keep first occurrence = earliest date)
      var seen = {};
      var events = [];
      allEvents.forEach(function(e) {
        var key = e.name.trim().toLowerCase();
        if (!seen[key]) { seen[key] = true; events.push(e); }
      });

      if (events.length === 0) {
        content.innerHTML = '<div class="events-empty">לא נמצאו אירועים בקטגוריה זו כרגע</div>';
        return;
      }

      var html = '<div class="events-grid-gyg">';
      events.forEach(function(e) {
        var flag = COUNTRY_FLAGS[e.countryCode] || '';
        var dateStr = formatDate(e.date);
        var thumbHtml = e.image
          ? '<img class="event-card__img" src="' + e.image + '" alt="" loading="lazy">'
          : '<div class="event-card__img-placeholder">' + icon + '</div>';

        var dealBadge = e.deal
          ? '<div class="event-card__deal-wrap"><span class="event-card__deal">🏷 מבצע</span></div>'
          : '';

        var priceHtml = e.priceMin != null
          ? '<span class="event-card__price">מ־' + Math.round(e.priceMin) + ' ' + (e.currency || '') + '</span>'
          : '<span></span>';

        html += '<a class="event-card" href="' + (e.url || '#') + '" target="_blank" rel="noopener">'
          + '<div class="event-card__thumb">' + thumbHtml + dealBadge + '</div>'
          + '<div class="event-card__body">'
          + '<div class="event-card__location">' + flag + ' ' + (e.city || '') + '</div>'
          + '<div class="event-card__name">' + e.name + '</div>'
          + (dateStr ? '<div class="event-card__date">📅 ' + dateStr + '</div>' : '')
          + '<div class="event-card__footer">'
          + priceHtml
          + '<span class="event-card__btn">כרטיסים</span>'
          + '</div>'
          + '</div></a>';
      });
      html += '</div>';
      content.innerHTML = html;
    }

    function setActiveTab(category) {
      activeCategory = category;
      document.querySelectorAll('.events-tab').forEach(function(tab) {
        tab.classList.toggle('active', tab.dataset.category === category);
      });
      if (eventsData) renderCards(category);
    }

    document.getElementById('events-tabs').addEventListener('click', function(e) {
      if (e.target.classList.contains('events-tab')) {
        searchMode = false;
        document.getElementById('events-search-input').value = '';
        setActiveTab(e.target.dataset.category);
      }
    });

    // Search
    var searchInput = document.getElementById('events-search-input');
    var searchBtn   = document.getElementById('events-search-btn');

    function doSearch() {
      var q = searchInput.value.trim();
      if (!q) return;
      searchMode = true;
      content.innerHTML = '<div class="events-loading">מחפש...</div>';

      fetch(SEARCH_URL + '?q=' + encodeURIComponent(q))
        .then(function(res) { return res.json(); })
        .then(function(data) {
          var results = data.results || [];
          if (results.length === 0) {
            content.innerHTML = '<div class="events-empty">לא נמצאו תוצאות עבור "' + q + '"</div>';
            return;
          }
          // Reuse renderCards logic with search results
          eventsData = eventsData || { events: {} };
          eventsData.events['__search__'] = results;
          renderCards('__search__');
        })
        .catch(function() {
          content.innerHTML = '<div class="events-empty">שגיאה בחיפוש, נסו שוב</div>';
        });
    }

    searchBtn.addEventListener('click', doSearch);
    searchInput.addEventListener('keydown', function(e) {
      if (e.key === 'Enter') doSearch();
    });

    function fetchEvents() {
      loaded = true;
      fetch(API_URL)
        .then(function(res) { return res.json(); })
        .then(function(data) {
          eventsData = data;
          renderCards(activeCategory);
        })
        .catch(function() {
          content.innerHTML = '<div class="events-empty">לא ניתן לטעון אירועים כרגע</div>';
        });
    }
  })();
